import {fillReportSignatures} from './report-signatures.js';
import {openSignatureReport} from './report-print.js';
import {summarize,reportCsv,statusLabel} from './report-metrics.js';
import {loadReportPages,filterReport,reportTime} from './report-data.js';
export function mountReport(root,client,eventId,parentCurrent){
 const panel=document.createElement('div');panel.className='panel report-panel';root.append(panel);const current=()=>parentCurrent()&&panel.isConnected;
 panel.innerHTML='<h3>รายงานกิจกรรม</h3><p class="sub">กรองตามวันที่สมัครโดยใช้เวลาไทย สถานะ และการเช็คอิน ข้อมูลเป็นผล ณ เวลาที่โหลด กดอัปเดตเพื่อรับข้อมูลล่าสุด</p><div class="report-filters"><label>สมัครตั้งแต่วันที่<input name="from" type="date"></label><label>ถึงวันที่<input name="to" type="date"></label><label>สถานะสมัคร<select name="status"><option value="all">ทั้งหมด</option><option value="pending">รอพิจารณา</option><option value="approved">อนุมัติแล้ว</option><option value="rejected">ปฏิเสธแล้ว</option><option value="cancelled">ยกเลิกแล้ว</option></select></label><label>การเช็คอิน<select name="checkin"><option value="all">ทั้งหมด</option><option value="yes">เช็คอินแล้ว</option><option value="no">ยังไม่เช็คอิน</option></select></label></div><div class="report-actions"><button type="button" class="report-load">โหลดรายงาน</button><button type="button" class="report-reset">ล้างตัวกรอง</button><button type="button" class="report-export primary" disabled>ดาวน์โหลด CSV ตามตัวกรอง</button></div><p role="status" class="report-status"></p><p class="sub report-note"></p><div class="report-summary"></div><div class="report-results"></div><div class="report-pages"></div>';
 const fields=panel.querySelector('.report-filters'),load=panel.querySelector('.report-load'),reset=panel.querySelector('.report-reset'),exportButton=panel.querySelector('.report-export'),status=panel.querySelector('.report-status'),note=panel.querySelector('.report-note'),summary=panel.querySelector('.report-summary'),results=panel.querySelector('.report-results'),pages=panel.querySelector('.report-pages');let items=null,filtered=[],busy=false,pageNumber=0,loadedAt='';
 const printButton=document.createElement('button');printButton.type='button';printButton.className='report-print primary';printButton.textContent='พิมพ์ / บันทึก PDF พร้อมลายเซ็น';panel.querySelector('.report-actions').append(printButton);
 const filters=()=>Object.fromEntries([...fields.querySelectorAll('input,select')].map(field=>[field.name,field.value]));
 function controls(){load.disabled=reset.disabled=busy;fields.querySelectorAll('input,select').forEach(field=>field.disabled=busy);exportButton.disabled=printButton.disabled=busy||!filtered.length}
 function draw(){if(!current())return;const signatureCells=[];summary.replaceChildren();results.replaceChildren();pages.replaceChildren();filtered=[];if(items===null){controls();return}
  try{filtered=filterReport(items,filters()).sort((a,b)=>(b.createdAtMs??-Infinity)-(a.createdAtMs??-Infinity)||a.id.localeCompare(b.id))}catch(error){status.textContent=error.message;controls();return}
  const counts=summarize(filtered);status.textContent='พบ '+filtered.length+' จาก '+items.length+' ใบสมัคร · โหลดเมื่อ '+loadedAt;
  const missing=items.filter(item=>!Number.isFinite(item.createdAtMs)).length;note.textContent=(missing?'มี '+missing+' รายการไม่ทราบวันที่สมัคร รายการเหล่านี้จะไม่รวมเมื่อเลือกช่วงวันที่ · ':'')+'ไม่รวมใบสมัครในถังขยะ · CSV ไม่มีภาพลายเซ็น ใช้ปุ่มพิมพ์ / PDF เมื่อต้องการรูป · ข้อมูลอาจเปลี่ยนระหว่างโหลดหลายหน้า';
  for(const [key,title] of [['total','ผู้สมัครตามตัวกรอง'],['pending','รอพิจารณา'],['approved','อนุมัติแล้ว'],['checkedIn','เช็คอินแล้ว'],['rejected','ปฏิเสธแล้ว'],['cancelled','ยกเลิกแล้ว']]){const box=document.createElement('div'),number=document.createElement('strong'),label=document.createElement('span');number.textContent=counts[key];label.textContent=title;box.append(number,label);summary.append(box)}
  const count=Math.max(1,Math.ceil(filtered.length/50));pageNumber=Math.min(pageNumber,count-1);
  if(!filtered.length){const p=document.createElement('p');p.textContent='ไม่มีข้อมูลตามตัวกรองนี้';results.append(p)}else{const table=document.createElement('table');table.className='review-table report-table';const caption=document.createElement('caption');caption.className='sr-only';caption.textContent='รายชื่อในรายงานตามตัวกรอง';table.append(caption);table.insertAdjacentHTML('beforeend','<thead><tr><th scope="col">เลขอ้างอิง</th><th scope="col">ชื่อ–นามสกุล</th><th scope="col">วันที่สมัคร (เวลาไทย)</th><th scope="col">สถานะ</th><th scope="col">เช็คอิน</th><th scope="col">ลายเซ็น</th></tr></thead>');const body=document.createElement('tbody');for(const item of filtered.slice(pageNumber*50,(pageNumber+1)*50)){const row=document.createElement('tr');row.className='report-row';for(const [title,text] of [['เลขอ้างอิง',item.referenceCode||item.id],['ชื่อ–นามสกุล',item.participantName],['วันที่สมัคร (เวลาไทย)',reportTime(item.createdAtMs)],['สถานะ',statusLabel[item.status]||item.status],['เช็คอิน',item.checkedIn?'แล้ว · '+reportTime(item.checkedInAtMs):'ยังไม่เช็คอิน']]){const cell=document.createElement('td');cell.dataset.label=title;cell.textContent=text;row.append(cell)}const signatureCell=document.createElement('td');signatureCell.dataset.label='ลายเซ็น';signatureCell.textContent=item.hasSignature?'กำลังโหลด…':'ยังไม่มีลายเซ็น';row.append(signatureCell);signatureCells.push({item,cell:signatureCell});body.append(row)}table.append(body);results.append(table);fillReportSignatures(signatureCells,client,eventId,()=>current()&&table.isConnected)}
  const previous=document.createElement('button'),next=document.createElement('button'),text=document.createElement('span');previous.textContent='ก่อนหน้า';next.textContent='ถัดไป';previous.disabled=pageNumber===0||busy;next.disabled=pageNumber===count-1||busy;text.textContent='หน้า '+(pageNumber+1)+' / '+count;previous.onclick=()=>{pageNumber--;draw()};next.onclick=()=>{pageNumber++;draw()};pages.append(previous,text,next);controls();
 }
 fields.onchange=()=>{pageNumber=0;draw()};reset.onclick=()=>{fields.querySelectorAll('input').forEach(field=>field.value='');fields.querySelectorAll('select').forEach(field=>field.value='all');pageNumber=0;draw()};
 load.onclick=async()=>{if(busy)return;busy=true;items=null;filtered=[];summary.replaceChildren();results.replaceChildren();pages.replaceChildren();note.textContent='';controls();status.textContent='กำลังโหลดรายงาน…';try{const data=await loadReportPages(client,eventId,current,count=>status.textContent='กำลังโหลด '+count+' รายการ…');if(data===null||!current())return;items=data;loadedAt=new Date().toLocaleString('th-TH',{timeZone:'Asia/Bangkok'});load.textContent='อัปเดตรายงาน';pageNumber=0;busy=false;draw()}catch(error){if(current())status.textContent=error.message||'โหลดไม่ครบ กรุณาลองใหม่'}finally{busy=false;if(current())controls()}};
 printButton.onclick=async()=>{if(busy||!filtered.length||!current())return;busy=true;controls();try{await openSignatureReport(client,eventId,{...filters()},current)}catch(error){if(current())status.textContent=error.message||'เตรียมรายงานไม่สำเร็จ'}finally{busy=false;if(current())controls()}};
 exportButton.onclick=async()=>{if(busy||!filtered.length)return;busy=true;const selected=[...filtered];controls();try{const context=await client.staffContext();if(!current())return;if(!context.admin&&!context.events.some(event=>event.id===eventId&&event.permissions?.includes('reports')))throw new Error('ไม่มีสิทธิ์รายงานกิจกรรมนี้แล้ว');const url=URL.createObjectURL(new Blob([reportCsv(selected)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='kusk-report-'+eventId+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){if(current())status.textContent=error.message}finally{busy=false;if(current())controls()}};
}
